                    // If receiptType is 'Return Receipt' or invoice deduction: Reduce stock
                    const isReturn = receiptForm.receiptType === 'Return Receipt';
                    const newStock = isReturn ? Math.max(0, m.stock - qtyVal) : m.stock + qtyVal;
