                              width: '38px', height: '38px', borderRadius: '10px',
                              background: 'linear-gradient(135deg, #2563EB, #3B82F6)',
                              display: 'flex', alignItems: 'center', justifyContent: 'center',
                              boxShadow: '0 2px 6px rgba(37,99,235,0.3)'
